add_filter( 'comment_form_defaults', 'perfectpixel_comment_length_field' );
add_filter( 'preprocess_comment', 'perfectpixel_comment_length_check' );

function perfectpixel_comment_length_max() {
	return max( 1, (int) '{{comment_max_chars}}' );
}

function perfectpixel_comment_length_field( $defaults ) {
	$max = perfectpixel_comment_length_max();
	$defaults['comment_field'] = preg_replace( '/<textarea\b/', '<textarea maxlength="' . $max . '"', $defaults['comment_field'], 1 );
	$defaults['comment_field'] .= '<p class="perfectpixel-comment-counter" aria-live="polite"><span>' . $max . '</span> ' . esc_html( '{{comment_counter_text}}' ) . '</p>';
	$defaults['comment_field'] .= '<script>( function () { var area = document.getElementById( "comment" ), out = document.querySelector( ".perfectpixel-comment-counter span" ); if ( ! area || ! out ) { return; } var max = ' . $max . '; var update = function () { out.textContent = Math.max( 0, max - area.value.length ); }; area.addEventListener( "input", update ); update(); } )();</script>';
	return $defaults;
}

function perfectpixel_comment_length_check( $commentdata ) {
	if ( ! empty( $commentdata['comment_type'] ) && 'comment' !== $commentdata['comment_type'] ) {
		return $commentdata; // Pingbacks, trackbacks, reviews of other types.
	}
	$text   = isset( $commentdata['comment_content'] ) ? $commentdata['comment_content'] : '';
	$length = function_exists( 'mb_strlen' ) ? mb_strlen( $text ) : strlen( $text );
	if ( $length > perfectpixel_comment_length_max() ) {
		wp_die( esc_html( '{{comment_too_long_message}}' ), '', array( 'response' => 400, 'back_link' => true ) );
	}
	if ( $length < (int) '{{comment_min_chars}}' ) {
		wp_die( esc_html( '{{comment_too_short_message}}' ), '', array( 'response' => 400, 'back_link' => true ) );
	}
	return $commentdata;
}
